// ==========================================================================
// Картинки нагород, вшиті в код. Окремі файли в assets/ більше не потрібні:
// один втрачений при деплої файл — і бот падає на sendPhoto.
// Base64 узято з тих самих зображень, що показує WebApp, тому в чаті
// і в застосунку людина бачить один і той самий приз.
// ==========================================================================

const B64 = {
  nft: '',
  bear: '',
  gift: '',
  rocket: '',
  trophy: '',
};

// Telegraf приймає Buffer як джерело фото — файл на диску не потрібен.
function photo(id) {
  const b = B64[id];
  if (!b) return null;
  return { source: Buffer.from(b, 'base64') };
}

module.exports = { B64, photo, has: (id) => !!B64[id] };
